import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry max_reduce_dim_3d_f32(
    .param .u64 p_in,
    .param .u64 p_out,
    .param .u32 p_D0,
    .param .u32 p_D1,
    .param .u32 p_D2,
    .param .u32 p_S0,
    .param .u32 p_S1,
    .param .u32 p_S2,
    .param .u32 p_red,
    .param .u32 p_Nout
)
{
    .reg .pred  %p_exit, %p0, %p1, %p_loop;
    .reg .b32   %r_tid, %r_ntid, %r_cta, %r_tmp;
    .reg .b32   %rD0, %rD1, %rD2, %rS0, %rS1, %rS2, %r_red, %rNout;
    .reg .b32   %r_q, %r_r, %r_i, %r_loop_end;
    .reg .b64   %rd_in, %rd_out, %rd_base, %rd_tmp, %rd_ptr, %rd_out_ptr, %rd_tid4, %rd_sk;

    .reg .f32   %f_max, %f_val;

    // Load params
    ld.param.u64  %rd_in,    [p_in];
    ld.param.u64  %rd_out,   [p_out];
    ld.param.u32  %rD0,      [p_D0];
    ld.param.u32  %rD1,      [p_D1];
    ld.param.u32  %rD2,      [p_D2];
    ld.param.u32  %rS0,      [p_S0];
    ld.param.u32  %rS1,      [p_S1];
    ld.param.u32  %rS2,      [p_S2];
    ld.param.u32  %r_red,    [p_red];
    ld.param.u32  %rNout,    [p_Nout];

    // Compute linear thread id
    mov.u32 %r_tmp, %tid.x;
    mov.u32 %r_ntid, %ntid.x;
    mov.u32 %r_cta, %ctaid.x;
    mad.lo.s32 %r_tid, %r_cta, %r_ntid, %r_tmp;

    // Bounds check
    setp.ge.u32 %p_exit, %r_tid, %rNout;
    @%p_exit bra DONE;

    // Defaults
    mov.u64 %rd_base, 0;
    mov.u64 %rd_sk, 0;

    // Branch by reduction dim
    setp.eq.u32 %p0, %r_red, 0;
    @%p0 bra RED0;
    setp.eq.u32 %p1, %r_red, 1;
    @%p1 bra RED1;

    // RED2: reduce over dim 2
RED2:
    // out dims (D0, D1): q = tid / D1, r = tid % D1
    div.u32 %r_q, %r_tid, %rD1;
    rem.u32 %r_r, %r_tid, %rD1;
    // base = q*S0 + r*S1
    mul.wide.u32 %rd_tmp, %r_q, %rS0;
    mov.u64 %rd_base, %rd_tmp;
    mul.wide.u32 %rd_tmp, %r_r, %rS1;
    add.u64 %rd_base, %rd_base, %rd_tmp;
    // stride for loop and loop end
    cvt.u64.u32 %rd_sk, %rS2;
    mov.b32 %r_loop_end, %rD2;
    bra AFTER_INDEX;

RED1:
    // reduce over dim 1, out dims (D0, D2): q = tid / D2, r = tid % D2
    div.u32 %r_q, %r_tid, %rD2;
    rem.u32 %r_r, %r_tid, %rD2;
    // base = q*S0 + r*S2
    mul.wide.u32 %rd_tmp, %r_q, %rS0;
    mov.u64 %rd_base, %rd_tmp;
    mul.wide.u32 %rd_tmp, %r_r, %rS2;
    add.u64 %rd_base, %rd_base, %rd_tmp;
    // stride for loop and loop end
    cvt.u64.u32 %rd_sk, %rS1;
    mov.b32 %r_loop_end, %rD1;
    bra AFTER_INDEX;

RED0:
    // reduce over dim 0, out dims (D1, D2): q = tid / D2, r = tid % D2
    div.u32 %r_q, %r_tid, %rD2;
    rem.u32 %r_r, %r_tid, %rD2;
    // base = q*S1 + r*S2
    mul.wide.u32 %rd_tmp, %r_q, %rS1;
    mov.u64 %rd_base, %rd_tmp;
    mul.wide.u32 %rd_tmp, %r_r, %rS2;
    add.u64 %rd_base, %rd_base, %rd_tmp;
    // stride for loop and loop end
    cvt.u64.u32 %rd_sk, %rS0;
    mov.b32 %r_loop_end, %rD0;

AFTER_INDEX:
    // Pointer to first element for this output
    add.u64 %rd_ptr, %rd_in, %rd_base;

    // Seed with first element along the reduction dimension
    ld.global.f32 %f_max, [%rd_ptr];

    // Loop over remaining elements
    mov.u32 %r_i, 1;
    setp.lt.u32 %p_loop, %r_i, %r_loop_end;
    @!%p_loop bra STORE;

LOOP:
    add.u64 %rd_ptr, %rd_ptr, %rd_sk;
    ld.global.f32 %f_val, [%rd_ptr];
    max.f32 %f_max, %f_max, %f_val;
    add.u32 %r_i, %r_i, 1;
    setp.lt.u32 %p_loop, %r_i, %r_loop_end;
    @%p_loop bra LOOP;

STORE:
    // Write result
    mul.wide.u32 %rd_tid4, %r_tid, 4;
    add.u64 %rd_out_ptr, %rd_out, %rd_tid4;
    st.global.f32 [%rd_out_ptr], %f_max;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("max_reduce_dim_3d_f32")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor")
        if x.dtype != torch.float32:
            raise RuntimeError("Only float32 is supported")
        if x.dim() != 3:
            raise RuntimeError("Only 3D tensors are supported")
        # Normalize dimension
        dim = self.dim
        if dim < 0:
            dim += x.dim()
        if dim < 0 or dim >= 3:
            raise RuntimeError("Invalid reduction dimension")

        D0, D1, D2 = [int(s) for s in x.shape]
        strides_elems = x.stride()
        itemsize = x.element_size()
        S0b = int(strides_elems[0] * itemsize)
        S1b = int(strides_elems[1] * itemsize)
        S2b = int(strides_elems[2] * itemsize)

        sizes = [D0, D1, D2]
        reduce_len = sizes[dim]
        if reduce_len <= 0:
            raise RuntimeError("Reduction dimension must be > 0")

        # Output shape: remove reduced dimension
        out_shape = [sizes[i] for i in range(3) if i != dim]
        N_out = int((D0 * D1 * D2) // reduce_len)

        out = torch.empty(out_shape, device=x.device, dtype=x.dtype)

        block_x = 256
        grid_x = (N_out + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "max_reduce_dim_3d_f32",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                out,
                u32(D0),
                u32(D1),
                u32(D2),
                u32(S0b),
                u32(S1b),
                u32(S2b),
                u32(int(dim)),
                u32(N_out),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
